---
import type { HTMLAttributes } from "astro/types"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"aside"> &
  VariantProps<typeof variants> & {
    storageKey?: string
  }

const variants = cva("py-2 relative flex items-center", {
  variants: {
    variant: {
      default: "bg-foreground text-background w-full",
      floating:
        "bg-background my-2 rounded-lg border shadow-sm mx-auto w-[calc(100%-2*var(--gutter,1rem))] max-w-[calc(var(--container,1280px)-2*var(--gutter,1rem))] overflow-hidden",
    },
  },
  defaultVariants: {
    variant: "default",
  },
})

const { class: className, variant, storageKey, ...props } = Astro.props
---

<aside
  class={cn(variants({ variant }), className)}
  data-slot="banner"
  data-banner-storage-key={storageKey}
  data-variant={variant}
  {...props}
>
  <slot />
</aside>

<script>
  const getStorageToken = (key: string) => `banner:${key}`

  const syncBanners = () => {
    document.querySelectorAll("[data-slot='banner']").forEach((banner) => {
      if (!(banner instanceof HTMLElement)) return
      const storageKey = banner.dataset.bannerStorageKey
      if (
        storageKey &&
        sessionStorage.getItem(getStorageToken(storageKey)) === "hidden"
      ) {
        banner.hidden = true
      }
    })
  }

  syncBanners()
  document.addEventListener("astro:page-load", syncBanners)

  document.addEventListener("click", (event) => {
    if (!(event.target instanceof Element)) return
    const closeButton = event.target.closest("[data-slot='banner-close']")
    const banner = closeButton?.closest("[data-slot='banner']")
    if (!(banner instanceof HTMLElement)) return
    banner.hidden = true
    const storageKey = banner.dataset.bannerStorageKey
    if (storageKey)
      sessionStorage.setItem(getStorageToken(storageKey), "hidden")
  })
</script>
